function act(obs, mem) {
  var DEG = Math.PI / 180, CS = 0.5, GW = 80, NC = 6400;
  var RAYA = [-60, -30, 0, 30, 60];
  var DX = [1, 1, 0, -1, -1, -1, 0, 1];
  var DY = [0, 1, 1, 1, 0, -1, -1, -1];
  var SQ = 1.41421356;

  function wr(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function cix(v) { var i = Math.floor(v / CS); return i < 0 ? 0 : (i > GW - 1 ? GW - 1 : i); }
  function gid(x, y) { return cix(y) * GW + cix(x); }

  function markFree(fx, fy) {
    var k = gid(fx, fy), o = mem.occ[k];
    if (o >= 5) return;
    mem.occ[k] = (o > 0) ? (o - 1) : -1;
  }
  function markBlk(bx, by, r) {
    var x0 = cix(bx - r), x1 = cix(bx + r), y0 = cix(by - r), y1 = cix(by + r);
    for (var yy = y0; yy <= y1; yy++) {
      for (var xx = x0; xx <= x1; xx++) {
        var ddx = (xx + 0.5) * CS - bx, ddy = (yy + 0.5) * CS - by;
        if (ddx * ddx + ddy * ddy <= r * r) {
          var k2 = yy * GW + xx;
          if (mem.occ[k2] < 5) mem.occ[k2]++;
        }
      }
    }
  }
  function ccost(k) {
    var o = mem.occ[k];
    if (o >= 3) return -1;
    var c = (o <= -1) ? 1.0 : (o === 0 ? 1.35 : (o === 1 ? 7 : 25));
    var t = mem.tab[k];
    if (t > 0 && mem.tk - t < 130) c += 25;
    return c;
  }
  function losOK(x0, y0, x1, y1, thr) {
    var dx = x1 - x0, dy = y1 - y0;
    var n = Math.ceil(Math.sqrt(dx * dx + dy * dy) / 0.22);
    if (n < 1) n = 1;
    for (var i = 1; i <= n; i++) {
      var t = i / n;
      if (mem.occ[gid(x0 + dx * t, y0 + dy * t)] > thr) return false;
    }
    return true;
  }
  function astar(sK, gK) {
    var aG = mem.aG, aP = mem.aP, aD = mem.aD, hI = mem.aHI, hK = mem.aHK;
    aG.fill(1e9); aP.fill(-1); aD.fill(0);
    var hn = 0, hmax = hI.length - 4;
    function push(ii, kk) {
      if (hn > hmax) return;
      var n = hn++;
      hI[n] = ii; hK[n] = kk;
      while (n > 0) {
        var p = (n - 1) >> 1;
        if (hK[p] <= hK[n]) break;
        var tt = hK[p]; hK[p] = hK[n]; hK[n] = tt;
        tt = hI[p]; hI[p] = hI[n]; hI[n] = tt;
        n = p;
      }
    }
    function pop() {
      var top = hI[0];
      hn--;
      hI[0] = hI[hn]; hK[0] = hK[hn];
      var n = 0;
      for (;;) {
        var l = 2 * n + 1, r = l + 1, m = n;
        if (l < hn && hK[l] < hK[m]) m = l;
        if (r < hn && hK[r] < hK[m]) m = r;
        if (m === n) break;
        var tt = hK[m]; hK[m] = hK[n]; hK[n] = tt;
        tt = hI[m]; hI[m] = hI[n]; hI[n] = tt;
        n = m;
      }
      return top;
    }
    var gx = gK % GW, gy = (gK - gx) / GW;
    aG[sK] = 0;
    push(sK, 0);
    while (hn > 0) {
      var u = pop();
      if (aD[u]) continue;
      aD[u] = 1;
      if (u === gK) break;
      var ux = u % GW, uy = (u - ux) / GW;
      for (var i = 0; i < 8; i++) {
        var nx = ux + DX[i], ny = uy + DY[i];
        if (nx < 0 || ny < 0 || nx >= GW || ny >= GW) continue;
        var v = ny * GW + nx;
        if (aD[v]) continue;
        var c = (v === gK) ? 1 : ccost(v);
        if (c < 0) continue;
        if (i & 1) {
          if (ccost(uy * GW + nx) < 0 || ccost(ny * GW + ux) < 0) continue;
        }
        var ng = aG[u] + ((i & 1) ? SQ : 1) * CS * c;
        if (ng < aG[v]) {
          aG[v] = ng; aP[v] = u;
          var hx = nx - gx, hy = ny - gy;
          push(v, ng + CS * Math.sqrt(hx * hx + hy * hy));
        }
      }
    }
    if (!aD[gK]) return null;
    var path = [], cur = gK;
    while (cur >= 0) { path.push(cur); cur = aP[cur]; }
    path.reverse();
    return path;
  }

  if (!mem.o) {
    mem.o = 1;
    mem.occ = new Int8Array(NC);
    mem.tab = new Float32Array(NC);
    for (var yy = 0; yy < GW; yy++) {
      for (var xx = 0; xx < GW; xx++) {
        var wx = (xx + 0.5) * CS, wy = (yy + 0.5) * CS;
        if (wx < 0.62 || wx > 39.38 || wy < 0.62 || wy > 39.38) mem.occ[yy * GW + xx] = 6;
      }
    }
    mem.aG = new Float32Array(NC);
    mem.aP = new Int32Array(NC);
    mem.aD = new Uint8Array(NC);
    mem.aHI = new Int32Array(NC * 8 + 64);
    mem.aHK = new Float32Array(NC * 8 + 64);
    mem.hB = 0; mem.hP = obs.heading; mem.iE = 0; mem.side = 1;
    mem.ex = obs.x; mem.ey = obs.y; mem.gx = obs.x; mem.gy = obs.y;
    mem.tk = 0; mem.path = null; mem.pTk = -999; mem.pi = 0;
    mem.pLen = 1e9; mem.bLen = 1e9; mem.bTk = 0;
    mem.esc = 0; mem.stk = 0; mem.tI = obs.targetIndex; mem.bf = [];
  }

  mem.tk++;
  var dt = 0.05;

  // ---- GPS freshness, compass-bias estimation ----
  var rawx = obs.x, rawy = obs.y;
  var fdx = rawx - mem.gx, fdy = rawy - mem.gy;
  var fresh = (fdx * fdx + fdy * fdy) > 0.0009;
  var bf = mem.bf;
  bf.push([rawx, rawy, obs.heading, fresh ? 1 : 0]);
  if (bf.length > 34) bf.shift();
  if (fresh) { mem.gx = rawx; mem.gy = rawy; }

  if (bf.length >= 26 && (mem.tk % 3) === 0) {
    var i0 = -1, i1 = -1, i;
    for (i = 0; i < bf.length; i++) if (bf[i][3]) { i0 = i; break; }
    for (i = bf.length - 1; i >= 0; i--) if (bf[i][3]) { i1 = i; break; }
    if (i0 >= 0 && i1 - i0 > 11) {
      var csx = 0, csy = 0;
      for (i = i0; i <= i1; i++) { var ha = bf[i][2] * DEG; csx += Math.cos(ha); csy += Math.sin(ha); }
      var hmean = Math.atan2(csy, csx) / DEG;
      var okk = true;
      for (i = i0; i <= i1; i++) if (Math.abs(wr(bf[i][2] - hmean)) > 26) { okk = false; break; }
      if (okk) {
        var ddx = bf[i1][0] - bf[i0][0], ddy = bf[i1][1] - bf[i0][1];
        var dsp = Math.sqrt(ddx * ddx + ddy * ddy);
        if (dsp > 1.1) {
          var est = wr(Math.atan2(ddy, ddx) / DEG - hmean);
          var dv = wr(est - mem.hB);
          if (Math.abs(dv) < 40) mem.hB = cl(mem.hB + 0.09 * dv, -35, 35);
        }
      }
    }
  }

  var hT = obs.heading + mem.hB;
  var sp0 = obs.speed;
  if (typeof sp0 !== 'number' || sp0 !== sp0) sp0 = 0;
  sp0 = cl(sp0, -3, 3);

  // ---- pose: dead reckoning + GPS correction ----
  var hr = hT * DEG;
  mem.ex += sp0 * Math.cos(hr) * dt;
  mem.ey += sp0 * Math.sin(hr) * dt;
  if (fresh) { mem.ex += 0.55 * (rawx - mem.ex); mem.ey += 0.55 * (rawy - mem.ey); }
  mem.ex += 0.015 * (rawx - mem.ex); mem.ey += 0.015 * (rawy - mem.ey);
  var px = mem.ex, py = mem.ey;

  // ---- rays ----
  var R = obs.rays;
  var dd = [10, 10, 10, 10, 10], hh = [0, 0, 0, 0, 0];
  for (var i = 0; i < 5; i++) {
    var vv = R[i];
    if (typeof vv !== 'number' || vv !== vv || vv <= 0) vv = 0.05;
    if (vv > 9.95) { dd[i] = 10; hh[i] = 0; }
    else { dd[i] = (vv > 10 ? 10 : vv); hh[i] = 1; }
  }

  // ---- map update ----
  for (var i = 0; i < 5; i++) {
    var a = (hT + RAYA[i]) * DEG, ca = Math.cos(a), sa = Math.sin(a);
    var fl = hh[i] ? (dd[i] - 0.5) : 8.5;
    for (var sd = 0.4; sd < fl; sd += 0.25) markFree(px + ca * sd, py + sa * sd);
    if (hh[i]) markBlk(px + ca * (dd[i] - 0.12), py + sa * (dd[i] - 0.12), 0.5);
  }

  // ---- obstacle geometry in body frame (fwd, left) ----
  var pts = [];
  for (var i = 0; i < 5; i++) {
    if (!hh[i]) continue;
    var a = RAYA[i] * DEG;
    pts.push([dd[i] * Math.cos(a), dd[i] * Math.sin(a)]);
  }
  for (var i = 0; i < 4; i++) {
    if (!hh[i] || !hh[i + 1]) continue;
    var a0 = RAYA[i] * DEG, a1 = RAYA[i + 1] * DEG;
    var f0 = dd[i] * Math.cos(a0), s0 = dd[i] * Math.sin(a0);
    var f1 = dd[i + 1] * Math.cos(a1), s1 = dd[i + 1] * Math.sin(a1);
    for (var kk = 1; kk <= 3; kk++) {
      var tt = kk / 4;
      pts.push([f0 + (f1 - f0) * tt, s0 + (s1 - s0) * tt]);
    }
  }

  var RC = 0.42, RR = 0.85;
  var stopC = 1e9, rep = 0, latMin = 10, nearS = 0;
  for (var i = 0; i < pts.length; i++) {
    var f = pts[i][0], s = pts[i][1], as = (s < 0 ? -s : s);
    if (f > -0.4 && f < 3.5 && as > 0.15 && as < 2.2 && as < latMin) latMin = as;
    if (f <= -0.1) continue;
    if (as < RC) {
      var dc = f - Math.sqrt(RC * RC - s * s);
      if (dc < stopC) { stopC = dc; nearS = s; }
    }
    if (as < RR && f > 0.02) {
      var dr = f - Math.sqrt(RR * RR - s * s);
      if (dr < 2.4) {
        var w = cl((2.4 - dr) / 2.4, 0, 1); w = w * w;
        var ang = Math.atan2(s, f) / DEG;
        if (ang < 0) ang = -ang;
