  for (var i = 0; i < 2; i++) if (hh[i]) { var lv = dd[i] * (RAYA[i] < 0 ? -Math.sin(RAYA[i] * DEG) : Math.sin(RAYA[i] * DEG)); if (lv < lR) lR = lv; }
