  if (tdist > 1.3 && (mem.path === null || mem.tk - mem.pTk > 8)) {
    var cp = astar(gid(px, py), gid(tx, ty));
    if (cp && cp.length > 0) {
      var pl = [];
      for (var i = 0; i < cp.length; i++) {
        var k3 = cp[i], cx3 = k3 % GW, cy3 = (k3 - cx3) / GW;
        pl.push([(cx3 + 0.5) * CS, (cy3 + 0.5) * CS]);
      }
      pl[0] = [px, py];
      pl[pl.length - 1] = [tx, ty];
      var outp = [pl[0]], ii = 0;
      while (ii < pl.length - 1) {
        var jj = pl.length - 1;
        while (jj > ii + 1 && !losOK(pl[ii][0], pl[ii][1], pl[jj][0], pl[jj][1], 1)) jj--;
        outp.push(pl[jj]); ii = jj;
      }
      mem.path = outp;
      var L2 = 0;
      for (var i = 1; i < outp.length; i++) {
        var q0 = outp[i - 1], q1 = outp[i];
        L2 += Math.sqrt((q1[0] - q0[0]) * (q1[0] - q0[0]) + (q1[1] - q0[1]) * (q1[1] - q0[1]));
      }
      mem.pLen = L2; mem.pi = 0;
    } else { mem.path = null; mem.pLen = 1e9; }
    mem.pTk = mem.tk;
  }

  // ---- aim point ----
  var ax = tx, ay = ty;
  var direct = (tdist < 3.0) && losOK(px, py, tx, ty, 0);
  if (!direct && mem.path && mem.path.length > 1) {
    var P2 = mem.path, bi = mem.pi, bd = 1e18;
    var lo = (mem.pi > 2) ? mem.pi - 2 : 0;
    for (var i = lo; i < P2.length; i++) {
      var qx = P2[i][0] - px, qy = P2[i][1] - py;
      var d3 = qx * qx + qy * qy;
      if (d3 < bd) { bd = d3; bi = i; }
    }
    mem.pi = bi;
    var rIdx = (bi + 1 < P2.length) ? bi + 1 : bi;
    var a0d = Math.atan2(P2[rIdx][1] - py, P2[rIdx][0] - px) / DEG;
    var L = cl(0.9 + 0.45 * (sp0 < 0 ? -sp0 : sp0), 0.9, 2.4);
    var ai = bi, acc = 0;
    while (ai < P2.length - 1 && acc < L) {
      var nd = Math.atan2(P2[ai + 1][1] - py, P2[ai + 1][0] - px) / DEG;
      if (Math.abs(wr(nd - a0d)) > 95) break;
      var sx0 = P2[ai + 1][0] - P2[ai][0], sy0 = P2[ai + 1][1] - P2[ai][1];
      acc += Math.sqrt(sx0 * sx0 + sy0 * sy0);
      ai++;
