  if (hh[2] && dd[2] < 2.2) rep += fs * cl((2.2 - dd[2]) * 42, 0, 85);
  rep = cl(rep, -95, 95);
  var err2 = wr(aimAng + rep - hT);

  if (Math.abs(err2) < 105) mem.iE = cl(mem.iE + err2 * dt, -35, 35);
  else mem.iE *= 0.88;
  var om = wr(hT - mem.hP) / dt; mem.hP = hT;
  var turn = 0.018 * err2 + 0.02 * mem.iE - 0.005 * om;
  turn = cl(turn, -1, 1);

  var af = (err2 < 0) ? -err2 : err2;
  var turnF = cl((80 - af) / 55, 0, 1);
  var xD = cl((stopC - 0.05) / 1.15, 0, 1);
  var decF = 0.22 + 0.78 * xD;
  var tight = 0.5 + 0.5 * cl((latMin - 0.5) / 0.75, 0, 1);
  var v = turnF * decF * tight;
  if (v > 0.04 && v < 0.22) v = 0.22;

