  if (stopC < 0.5) {
    turn = cl(turn + aw * 0.5, -1, 1);
    if (v > 0.35) v = 0.35;
  }
  if (stopC < 0.1) { v = 0; turn = aw; }

  // ---- stuck handling ----
  function tabooAhead() {
    for (var s2 = 0.5; s2 <= 2.6; s2 += 0.5) {
      for (var a2 = -30; a2 <= 30; a2 += 15) {
        var ar2 = (hT + a2) * DEG;
        mem.tab[gid(px + Math.cos(ar2) * s2, py + Math.sin(ar2) * s2)] = mem.tk;
      }
    }
  }
  var spm = (sp0 < 0) ? -sp0 : sp0;
  if (v > 0.2 && spm < 0.05) mem.stk++; else if (mem.stk > 0) mem.stk--;
  if (mem.stk > 12 && mem.esc <= 0) { mem.esc = 26; mem.stk = 0; tabooAhead(); mem.path = null; }
  if (mem.esc <= 0) {
    if (mem.pLen < mem.bLen - 0.4) { mem.bLen = mem.pLen; mem.bTk = mem.tk; }
    if (mem.tk - mem.bTk > 100) { mem.esc = 28; mem.bTk = mem.tk; mem.bLen = 1e9; tabooAhead(); mem.path = null; }
  }
  if (mem.esc > 0) {
    mem.esc--;
    var oside = (lL > lR) ? 1 : -1;
    if (mem.esc > 13) {
      var bkx = px - Math.cos(hT * DEG) * 0.7, bky = py - Math.sin(hT * DEG) * 0.7;
      if (mem.occ[gid(bkx, bky)] <= 0) { v = -0.55; turn = 0; }
      else { v = 0; turn = oside; }
    } else { v = 0; turn = oside; }
    if (mem.esc === 0) mem.path = null;
  }

  var left = v - turn, right = v + turn;
  var m = Math.max(1, Math.abs(left), Math.abs(right));
  left /= m; right /= m;
  return { left: left, right: right };
}

function act(obs, mem) {
  var D = Math.PI / 180;

  if (!mem.init) {
    mem.init = 1;
    mem.tk = 0;
    mem.pX = obs.x;
    mem.pY = obs.y;
    mem.pH = obs.heading;
    mem.pHc = obs.heading;
    mem.sx = obs.x;
    mem.sy = obs.y;
    mem.hB = 0;
    mem.gX = obs.x;
    mem.gY = obs.y;
    mem.stk = 0;
    mem.esc = 0;
    mem.mode = 0;
    mem.wS = 1;
    mem.tI = obs.targetIndex;
    mem.minD = 999;
    mem.noP = 0;
    mem.occ = new Int8Array(6400);
    mem.tb = new Int32Array(6400);
    for (var y = 0; y < 80; y++)
      for (var x = 0; x < 80; x++) {
        var wx = (x + 0.5) * 0.5, wy = (y + 0.5) * 0.5;
        if (wx < 0.55 || wx > 39.45 || wy < 0.55 || wy > 39.45)
          mem.occ[y * 80 + x] = 40;
      }
  }
  mem.tk++;

  function wr(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function gid(x, y) {
    return cl(Math.floor(y / 0.5), 0, 79) * 80 + cl(Math.floor(x / 0.5), 0, 79);
  }

  var px = obs.x, py = obs.y;
  var hR = obs.heading;
  var h = wr(hR + mem.hB);
  var sp = (typeof obs.speed === 'number' && obs.speed === obs.speed) ? obs.speed : 0;
  var R = obs.rays;
  var RA = [-60, -30, 0, 30, 60];

  mem.sx += 0.3 * (px - mem.sx);
  mem.sy += 0.3 * (py - mem.sy);
  var sx = mem.sx, sy = mem.sy;

  // GPS heading bias correction (conservative)
  var gdx = px - mem.gX, gdy = py - mem.gY;
  var gd2 = gdx * gdx + gdy * gdy;
  if (gd2 > 0.36 && gd2 < 25) {
    var gpsH = Math.atan2(gdy, gdx) / D;
    var he = wr(gpsH - h);
    var hc = wr(hR - mem.pH);
    if (sp > 0.2 && Math.abs(hc) < 15 && Math.abs(he) < 40)
      mem.hB = cl(mem.hB + he * 0.02, -25, 25);
    mem.gX = px;
    mem.gY = py;
  }
  mem.pH = hR;

  // Map update from rays
  for (var i = 0; i < 5; i++) {
    var a = (h + RA[i]) * D, ca = Math.cos(a), sa = Math.sin(a);
    var r = R[i];
    if (typeof r !== 'number' || r !== r || r <= 0) r = 0.05;
    var hit = r < 9.9, md = hit ? r : 8;
    for (var d = 0.4; d < md - 0.3; d += 0.25) {
      var k = gid(sx + ca * d, sy + sa * d);
      if (mem.occ[k] < 25) mem.occ[k] = Math.max(mem.occ[k] - 1, -3);
    }
    if (hit) {
      for (var e = -1; e <= 1; e++)
        for (var f = -1; f <= 1; f++) {
          var k2 = gid(sx + ca * (r - 0.1) + e * 0.3, sy + sa * (r - 0.1) + f * 0.3);
          if (mem.occ[k2] < 25) mem.occ[k2] = Math.min(mem.occ[k2] + 2, 20);
        }
    }
  }

  // Target and mode
  var tx = obs.targetX, ty = obs.targetY;
  if (obs.targetIndex !== mem.tI) {
    mem.tI = obs.targetIndex;
    mem.stk = 0; mem.esc = 0; mem.mode = 0;
    mem.minD = 999; mem.noP = 0;
    mem.tb.fill(0);
  }

  var dx = tx - px, dy = ty - py;
  var dist = Math.sqrt(dx * dx + dy * dy);

  if (dist < mem.minD - 0.15) { mem.minD = dist; mem.noP = 0; }
  else mem.noP++;

  // Line of sight check
  var los = true;
  if (dist > 0.5) {
    var nL = Math.max(1, Math.ceil(dist / 0.35));
    for (var i = 1; i < nL && los; i++)
      if (mem.occ[gid(px + dx * i / nL, py + dy * i / nL)] >= 10) los = false;
  }

  // Mode: 0=direct, 1=wall-follow
  if (los || dist < 1.5) mem.mode = 0;
