  var priorAvg = (mem.outL + mem.outR) * 0.5;
  var priorDiff = Math.abs(mem.outR - mem.outL);

  var straightMotion =
    priorAvg > 0.38 &&
    priorDiff < 0.18 &&
    forwardSpeed > 0.20 &&
    mem.mode !== 2;

  if (straightMotion) {
    mem.straightTime += dt;
  } else {
    mem.straightTime = Math.max(
      0,
      mem.straightTime - dt * 1.5
    );
  }

  if (
    straightMotion &&
    courseValid &&
    mem.straightTime > 0.50 &&
    now - mem.biasUpdate > 0.22
  ) {
    var biasError = wrap(gpsCourse - mem.hFilt);

    if (
      (!mem.biasReady && Math.abs(biasError) < 150) ||
      (mem.biasReady && Math.abs(biasError) < 95)
    ) {
      if (!mem.biasReady) {
        mem.bias = biasError * 0.42;
        mem.biasReady = true;
      } else {
        mem.bias = wrap(
          mem.bias + 0.030 * wrap(biasError - mem.bias)
        );
      }

      mem.bias = clamp(wrap(mem.bias), -65, 65);
      mem.biasUpdate = now;
    }
  }

  var navHeading = wrap(
    mem.hFilt + clamp(mem.bias, -65, 65)
  );

  var instantaneousRate =
    wrap(mem.hFilt - mem.prevH) / Math.max(dt, 0.05);

  instantaneousRate = clamp(
    instantaneousRate,
    -360,
    360
  );

  mem.hRate =
    mem.hRate * 0.76 +
    instantaneousRate * 0.24;

  mem.prevH = mem.hFilt;

  if (courseValid && forwardSpeed > 0.42) {
    var courseWeight = 0.04;

    if (straightMotion) {
      courseWeight = 0.28;
    } else if (Math.abs(mem.hRate) < 90) {
      courseWeight = 0.13;
    }

    navHeading = mixAngle(
      navHeading,
      gpsCourse,
      courseWeight
    );
  }

  var ranges = [];

  for (i = 0; i < 5; i++) {
    var oldRange = num(mem.rf[i], rawRays[i]);

    if (rawRays[i] < oldRange) {
      mem.rf[i] =
        oldRange * 0.38 +
        rawRays[i] * 0.62;
    } else {
      mem.rf[i] =
        oldRange * 0.89 +
        rawRays[i] * 0.11;
    }

    ranges[i] = Math.min(
      rawRays[i],
      mem.rf[i] + 0.30
    );
  }

  if (rawAhead < mem.af) {
    mem.af =
      mem.af * 0.40 +
      rawAhead * 0.60;
  } else {
    mem.af =
      mem.af * 0.89 +
      rawAhead * 0.11;
  }

  var aheadRange = Math.min(
    rawAhead,
    mem.af + 0.30
  );

  var front = Math.min(
    ranges[2],
    aheadRange
  );

  var rightNear = Math.min(
    ranges[0],
    ranges[1]
  );

  var leftNear = Math.min(
    ranges[3],
    ranges[4]
  );

  var rightClear = rightNear;
  var leftClear = leftNear;
  var sideNear = Math.min(
    rightNear,
    leftNear
  );

  var targetError = wrap(
    mem.bearing - navHeading
  );

  var absTargetError = Math.abs(targetError);

  var rayAngles = [-60, -30, 30, 60];
  var rayIndices = [0, 1, 3, 4];
  var rayWeights = [0.78, 1.04, 1.04, 0.78];
  var repulsion = 0;

  for (i = 0; i < 4; i++) {
    var ri = rayIndices[i];
    var safeRange =
      (i === 0 || i === 3) ? 2.30 : 2.95;

    var closeFraction = clamp(
      (safeRange - ranges[ri]) / safeRange,
      0,
      1
    );

    repulsion +=
      -Math.sin(rayAngles[i] * PI / 180) *
      closeFraction *
      closeFraction *
      rayWeights[i];
  }

  repulsion = clamp(
    repulsion,
    -1.0,
    1.0
  );

  var sidePush = 0;

  if (rightNear < 2.20) {
    sidePush +=
      clamp((2.20 - rightNear) / 1.65, 0, 1) *
      0.52;
  }

  if (leftNear < 2.20) {
    sidePush -=
      clamp((2.20 - leftNear) / 1.65, 0, 1) *
      0.52;
  }

  sidePush = clamp(
    sidePush,
    -0.60,
    0.60
  );

  var boundaryMargin = 2.05;
  var bdx = 0;
  var bdy = 0;

  if (x < boundaryMargin) {
    bdx += boundaryMargin - x;
  }

  if (x > 40 - boundaryMargin) {
    bdx -= x - (40 - boundaryMargin);
  }

  if (y < boundaryMargin) {
    bdy += boundaryMargin - y;
  }

  if (y > 40 - boundaryMargin) {
    bdy -= y - (40 - boundaryMargin);
  }

  var boundaryMagnitude = Math.sqrt(
    bdx * bdx + bdy * bdy
  );

  var boundaryPressure = clamp(
    boundaryMagnitude / 1.75,
    0,
    1
  );

  var boundaryTurn = 0;

  if (boundaryMagnitude > 0.01) {
    var boundaryBearing =
      Math.atan2(bdy, bdx) * 180 / PI;

    boundaryTurn =
      clamp(
        wrap(boundaryBearing - navHeading) / 90,
        -1,
        1
      ) *
      (0.17 + 0.37 * boundaryPressure);
  }

  var headingDamp =
    clamp(mem.hRate / 180, -1, 1) *
    0.10;

  if (dist < mem.bestDist - 0.10) {
    mem.bestDist = dist;
    mem.lastProgress = now;
  }

  var intentionalTurn =
    mem.mode === 0 &&
    absTargetError > 115;

  if (now - mem.sampleT >= 0.45) {
    var loopFound = false;

    if (
      now - mem.lastProgress > 3.0 &&
      now - mem.targetStart > 2.5 &&
      dist > 1.15
    ) {
      for (i = 0; i < mem.samples.length; i++) {
        var sample = mem.samples[i];

        if (
          sample.idx === idx &&
          now - sample.t > 2.8
        ) {
          var sdx = x - sample.x;
          var sdy = y - sample.y;
          var sampleDistance = Math.sqrt(
            sdx * sdx + sdy * sdy
          );

          if (
            sampleDistance < 0.95 &&
            dist > mem.bestDist - 0.25
          ) {
            loopFound = true;
            break;
          }
        }
      }
    }

    mem.samples.push({
      x: x,
      y: y,
      t: now,
      idx: idx
    });

    while (mem.samples.length > 110) {
      mem.samples.shift();
    }

    mem.sampleT = now;

    if (loopFound) {
      mem.loop = true;
    }
  }

  if (
    priorAvg > 0.25 &&
    Math.abs(speed) < 0.14 &&
    priorDiff < 0.80 &&
    front > 0.80 &&
    !intentionalTurn
  ) {
    mem.still += dt;
  } else {
    mem.still = Math.max(
      0,
      mem.still - dt * 0.60
    );
  }

  function clearanceSide() {
    if (leftClear > rightClear + 0.20) {
      return 1;
    }

    if (rightClear > leftClear + 0.20) {
      return -1;
    }

    if (targetError > 28 && leftClear > 0.80) {
      return 1;
    }

    if (targetError < -28 && rightClear > 0.80) {
      return -1;
    }

    return mem.lastSide || 1;
  }

  function regulateBase(base) {
    if (forwardSpeed > 1.15) {
      base -= clamp(
        (forwardSpeed - 1.15) * 0.38,
        0,
        0.38
      );
    }

    if (forwardSpeed > 1.65) {
      base -= clamp(
        (forwardSpeed - 1.65) * 0.75,
        0,
        0.25
      );
    }

    if (boundaryPressure > 0.50) {
      base -=
        clamp(
          (boundaryPressure - 0.50) * 0.25,
          0,
          0.16
        );
    }

    return clamp(
      base,
      -0.24,
      0.72
    );
  }

  function emit(leftWanted, rightWanted, urgent) {
    leftWanted = clamp(
      leftWanted,
      -1,
      1
    );

    rightWanted = clamp(
      rightWanted,
      -1,
      1
    );

    var rate = urgent ? 0.42 : 0.20;

    if (
      front < 0.82 ||
      sideNear < 0.72
    ) {
      rate = 0.50;
    }

    var step =
      rate *
      clamp(dt / 0.05, 0.5, 3.0);

    mem.outL += clamp(
      leftWanted - mem.outL,
      -step,
      step
    );

    mem.outR += clamp(
      rightWanted - mem.outR,
      -step,
      step
    );

    mem.outL = clamp(
      mem.outL,
      -1,
      1
    );

    mem.outR = clamp(
      mem.outR,
      -1,
      1
    );

    mem.lastAvg =
      (mem.outL + mem.outR) * 0.5;

    mem.lastDiff =
      Math.abs(mem.outR - mem.outL);

    mem.lastMode = mem.mode;

    return {
      left: mem.outL,
      right: mem.outR
    };
  }

  function corridorDrive() {
    var centerTurn =
      (leftNear - rightNear) * 0.40 +
      clamp(targetError * 0.0018, -0.20, 0.20) +
      repulsion * 0.70 +
      sidePush * 0.45 +
      boundaryTurn -
      headingDamp * 0.45;

    centerTurn = clamp(
      centerTurn,
      -0.48,
      0.48
    );

    var corridorBase;

    if (front < 1.30) {
      corridorBase = 0.13;
    } else if (front < 2.05) {
      corridorBase = 0.24;
    } else if (front < 3.0) {
      corridorBase = 0.35;
    } else {
      corridorBase = 0.46;
    }

    if (sideNear < 0.72) {
      corridorBase *= 0.68;
    }

    if (absTargetError > 115) {
      corridorBase *= 0.72;
    }

    if (dist < 1.25) {
      corridorBase = Math.min(
        corridorBase,
        0.32
      );
    }

    if (dist < 0.80) {
      corridorBase = Math.min(
        corridorBase,
        0.22
      );
    }

    if (dist < 0.52) {
      corridorBase = Math.min(
        corridorBase,
        0.11
      );
    }

    corridorBase = regulateBase(
      corridorBase
    );

    return emit(
      corridorBase - centerTurn,
      corridorBase + centerTurn,
      front < 0.92 ||
      sideNear < 0.60
    );
  }

  var noProgress =
    now - mem.lastProgress > 7.0 &&
    now - mem.targetStart > 4.0;

  var needRecovery =
    mem.loop ||
    mem.still > 2.05 ||
    (mem.mode === 1 && noProgress);

  if (
    needRecovery &&
    mem.mode !== 2 &&
    dist > 1.12 &&
    now >= mem.recoverCooldown
  ) {
    var previousMode = mem.mode;
    var recoverySide;

    if (
      previousMode === 1 &&
      mem.side &&
      Math.abs(leftClear - rightClear) < 0.50
    ) {
      recoverySide = -mem.side;
    } else {
      recoverySide = clearanceSide();
    }

    mem.mode = 2;
    mem.recoverFrom = previousMode;
    mem.recoverStart = now;
    mem.recoverSide = recoverySide;
    mem.lastSide = recoverySide;

    mem.loop = false;
    mem.still = 0;
    mem.leaveSince = 0;
    mem.samples = [];
    mem.sampleT = now;
    mem.bestDist = dist;
    mem.lastProgress = now;
    mem.hardUntil = 0;
  }

  if (mem.mode === 2) {
    var recoveryAge =
      now - mem.recoverStart;

    var recoverySideNow =
      mem.recoverSide || 1;

    if (
      recoveryAge > 0.25 &&
      front < 1.35 &&
      Math.abs(leftClear - rightClear) > 0.30
    ) {
      recoverySideNow = clearanceSide();
      mem.recoverSide = recoverySideNow;
    }

    if (recoveryAge < 0.68) {
      var pivotBase =
        front < 0.82 ? -0.12 : -0.025;

      var pivotTurn = 0.66;

      return emit(
        pivotBase - pivotTurn * recoverySideNow,
        pivotBase + pivotTurn * recoverySideNow,
        true
      );
    }

    if (recoveryAge < 1.58) {
      var recoveryBase =
        front < 1.30 ? 0.05 : 0.20;

      var recoveryTurn = 0.36;

      recoveryBase = regulateBase(
        recoveryBase
      );

      return emit(
        recoveryBase - recoveryTurn * recoverySideNow,
        recoveryBase + recoveryTurn * recoverySideNow,
        true
      );
    }

    mem.recoverCooldown = now + 1.10;

    if (mem.recoverFrom === 1) {
      mem.mode = 1;
      mem.side = recoverySideNow;
      mem.lastSide = recoverySideNow;
      mem.avoidStart = now;
      mem.avoidMin = now + 1.15;
      mem.lastSwitch = now;
      mem.leaveSince = 0;
    } else {
      mem.mode = 0;
      mem.side = 0;
      mem.avoidCooldown = now + 1.00;
      mem.lastProgress = now;
    }

    mem.bestDist = dist;
    mem.loop = false;
  }

  if (front < 0.78) {
    if (!(mem.hardUntil > now)) {
      mem.hardSide = clearanceSide();
      mem.hardUntil = now + 0.44;
    }

    var hardSide = mem.hardSide || 1;
    var oldHardMode = mem.mode;

    mem.mode = 1;
    mem.side = hardSide;
    mem.lastSide = hardSide;
    mem.leaveSince = 0;

    if (oldHardMode !== 1) {
      mem.avoidStart = now;
      mem.avoidMin = now + 0.95;
    }

    var hardBase =
      front < 0.48 ? -0.16 : -0.045;

    var hardTurn =
      front < 0.48 ? 0.76 : 0.68;

    return emit(
      hardBase - hardTurn * hardSide,
      hardBase + hardTurn * hardSide,
      true
    );
  }

  var narrowLimit =
    1.64 +
    0.12 * clamp(forwardSpeed / 1.5, 0, 1);

  var narrowNow =
    front > 0.96 &&
    leftNear < narrowLimit &&
    rightNear < narrowLimit;

  if (narrowNow) {
    return corridorDrive();
  }

  var sideLimit =
    1.58 +
    0.18 * clamp(forwardSpeed / 1.5, 0, 1);

  var leftOnly =
    leftNear < sideLimit &&
    leftNear + 0.18 < rightNear;

  var rightOnly =
    rightNear < sideLimit &&
    rightNear + 0.18 < leftNear;

  if (leftOnly || rightOnly) {
    var observedSide =
      leftOnly ? -1 : 1;

    if (!(mem.sideHoldUntil > now)) {
      mem.sideHold = observedSide;
      mem.sideHoldUntil = now + 0.38;
    }

    var awaySide =
      mem.sideHold || observedSide;

    if (
      awaySide < 0 &&
      leftNear > sideLimit + 0.22
    ) {
      awaySide = observedSide;
      mem.sideHold = awaySide;
      mem.sideHoldUntil = now + 0.38;
    }

    if (
      awaySide > 0 &&
      rightNear > sideLimit + 0.22
    ) {
      awaySide = observedSide;
      mem.sideHold = awaySide;
      mem.sideHoldUntil = now + 0.38;
    }

    var oldSideMode = mem.mode;

    mem.mode = 1;
    mem.side = awaySide;
    mem.lastSide = awaySide;
    mem.leaveSince = 0;

    if (oldSideMode !== 1) {
      mem.avoidStart = now;
      mem.avoidMin = now + 0.90;
    }

    var closeSideRange =
      awaySide < 0 ? leftNear : rightNear;

    var sideStrength =
      0.44 +
      0.30 *
      clamp(
        (sideLimit - closeSideRange) / 0.85,
        0,
        1
      );

    var sideTurn =
      awaySide * sideStrength +
      repulsion * 0.35 +
      sidePush * 0.35 +
      boundaryTurn * 0.60 -
      headingDamp * 0.35;

    if (awaySide < 0) {
      sideTurn = Math.min(
        sideTurn,
        -0.30
      );
    } else {
      sideTurn = Math.max(
        sideTurn,
        0.30
      );
    }

    sideTurn = clamp(
      sideTurn,
      -0.78,
      0.78
    );

    var sideBase;

    if (closeSideRange < 1.12) {
      sideBase = -0.05;
    } else if (closeSideRange < 1.42) {
      sideBase = 0.035;
    } else {
      sideBase = 0.12;
    }

    if (front < 2.10) {
      sideBase -= 0.045;
    }

    if (forwardSpeed > 1.25) {
      sideBase -= 0.04;
    }

    return emit(
      sideBase - sideTurn,
      sideBase + sideTurn,
      true
    );
  }

  if (
    mem.mode === 0 &&
    now >= mem.avoidCooldown
  ) {
    var forwardTrigger =
      3.72 +
      0.34 * clamp(forwardSpeed / 1.5, 0, 1);

    var angledThreat =
      ranges[1] < 2.38 ||
      ranges[3] < 2.38 ||
      ranges[0] < 1.70 ||
      ranges[4] < 1.70;

    var sideThreat =
      sideNear < 1.98;

    if (
      front < forwardTrigger ||
      angledThreat ||
      sideThreat
    ) {
      var leftScore = leftClear;
      var rightScore = rightClear;

      if (targetError > 22) {
        leftScore += 0.50;
      }

      if (targetError < -22) {
        rightScore += 0.50;
      }

      if (targetError > 70) {
        leftScore += 0.15;
      }

      if (targetError < -70) {
        rightScore += 0.15;
      }

      if (leftClear < 0.82) {
        leftScore -= 0.80;
      }

      if (rightClear < 0.82) {
        rightScore -= 0.80;
      }

      if (
        front < 1.40 &&
        leftClear > rightClear + 0.15
      ) {
        mem.side = 1;
      } else if (
        front < 1.40 &&
        rightClear > leftClear + 0.15
      ) {
        mem.side = -1;
      } else if (leftScore > rightScore + 0.16) {
        mem.side = 1;
      } else if (rightScore > leftScore + 0.16) {
        mem.side = -1;
      } else {
        mem.side = mem.lastSide || 1;
      }

      mem.mode = 1;
      mem.lastSide = mem.side;
      mem.avoidStart = now;
      mem.avoidMin = now + 1.08;
      mem.lastSwitch = now;
      mem.leaveSince = 0;
      mem.still = 0;
    }
  }

  if (mem.mode === 1) {
    var side = mem.side || 1;
    var followAge =
      now - mem.avoidStart;

    if (
      followAge > 0.85 &&
      now - mem.lastSwitch > 1.0 &&
      front < 2.15
    ) {
      var routeClearance =
        side > 0 ? leftNear : rightNear;

      var otherClearance =
        side > 0 ? rightNear : leftNear;

      if (
        routeClearance < 0.78 &&
        otherClearance > routeClearance + 0.36
      ) {
        side = -side;
        mem.side = side;
        mem.lastSide = side;
        mem.lastSwitch = now;
        mem.leaveSince = 0;
      }
    }

    var wall =
      side > 0 ? rightNear : leftNear;

    var routeRange =
      side > 0 ? leftNear : rightNear;

    var targetSideRange;

    if (targetError < -75) {
      targetSideRange = ranges[0];
    } else if (targetError < -38) {
      targetSideRange = ranges[1];
    } else if (targetError > 75) {
      targetSideRange = ranges[4];
    } else {
      targetSideRange = ranges[3];
    }

    var targetAligned =
      absTargetError < 31 ||
      side * targetError > -18;

    var gapLeave =
      side * targetError < -48 &&
      targetSideRange > 2.30 &&
      front > 3.75 &&
      wall > 0.95;

    var lateLeave =
      followAge > 5.60 &&
      front > 4.00 &&
      wall > 2.40 &&
      side * targetError > -55;

    var canLeave =
      followAge > 1.10 &&
      now >= mem.avoidMin &&
      front > 3.72 &&
      routeRange > 1.02 &&
      wall > 0.84 &&
      (targetAligned || gapLeave || lateLeave);

    if (canLeave) {
      if (!(mem.leaveSince > 0)) {
        mem.leaveSince = now;
      }

      if (now - mem.leaveSince > 0.36) {
        mem.mode = 0;
        mem.side = 0;
        mem.leaveSince = 0;
        mem.avoidCooldown = now + 1.05;
      }
    } else {
      mem.leaveSince = 0;
    }

    if (mem.mode === 1) {
      if (
        front > 1.02 &&
        leftNear < narrowLimit &&
        rightNear < narrowLimit
      ) {
        return corridorDrive();
      }

      var frontFraction = clamp(
        (4.00 - front) / 2.85,
        0,
        1
      );

      var followTurn =
        side *
        (0.060 + 0.66 * frontFraction);

      if (followAge < 0.68) {
        followTurn += side * 0.095;
      }

      if (wall < 2.55) {
        var wallCorrection = clamp(
          (1.25 - wall) * 0.30,
          -0.30,
          0.40
        );

        followTurn += side * wallCorrection;
      }

      if (routeRange < 1.82) {
        followTurn +=
          -side *
          clamp(
            (1.82 - routeRange) * 0.30,
            0,
            0.32
          );
      }

      followTurn += clamp(
        targetError * 0.0022,
        -0.17,
        0.17
      );

      followTurn += repulsion * 1.02;
      followTurn += sidePush * 0.50;
      followTurn += boundaryTurn * 1.10;
      followTurn -= headingDamp * 0.55;

      followTurn = clamp(
        followTurn,
        -0.72,
        0.72
      );

      var followBase;

      if (front < 0.84) {
        followBase = 0.025;
      } else if (front < 1.28) {
        followBase = 0.10;
      } else if (front < 1.92) {
        followBase = 0.20;
      } else if (front < 2.70) {
        followBase = 0.32;
      } else if (front < 3.82) {
        followBase = 0.45;
      } else {
        followBase = 0.55;
      }

      if (wall < 1.00) {
        followBase *= 0.74;
      }

      if (routeRange < 1.50) {
        followBase *= 0.66;
      }

      if (sideNear < 1.90) {
        followBase *= 0.72;
      }

      if (absTargetError > 108) {
        followBase = Math.min(
          followBase,
          0.21
        );
      }

      if (boundaryPressure > 0.40) {
        followBase *=
          1 - 0.22 * boundaryPressure;
      }

      if (dist < 1.25) {
        followBase = Math.min(
          followBase,
          0.35
        );
      }

      if (dist < 0.82) {
        followBase = Math.min(
          followBase,
          0.23
        );
      }

      if (dist < 0.52) {
        followBase = Math.min(
          followBase,
          0.115
        );
      }

      followBase = regulateBase(
        followBase
      );

      return emit(
        followBase - followTurn,
        followBase + followTurn,
        front < 0.96 ||
        sideNear < 1.18
      );
    }
  }

  if (
    front > 1.02 &&
    leftNear < narrowLimit &&
    rightNear < narrowLimit
  ) {
    return corridorDrive();
  }

  var seekTurn = clamp(
    targetError * 0.0045,
    -0.54,
    0.54
  );

  seekTurn += repulsion * 1.00;
  seekTurn += sidePush * 0.58;
  seekTurn += boundaryTurn;
  seekTurn -= headingDamp;

  if (absTargetError > 125) {
    seekTurn +=
      targetError > 0 ? 0.08 : -0.08;
  }

  seekTurn = clamp(
    seekTurn,
    -0.72,
    0.72
  );

  var seekBase;

  if (absTargetError < 20) {
    seekBase = 0.62;
  } else if (absTargetError < 48) {
    seekBase = 0.57;
  } else if (absTargetError < 82) {
    seekBase = 0.46;
  } else if (absTargetError < 118) {
    seekBase = 0.30;
