      mem.calibDone = true;
      mem.lastX = obs.x;
      mem.lastY = obs.y;
    }
  }

  const dx = obs.x - mem.lastX;
  const dy = obs.y - mem.lastY;
  const moveDist = Math.hypot(dx, dy);
  mem.lastX = obs.x;
  mem.lastY = obs.y;

  // Continuous heading estimate from GPS velocity, with stronger update when going straight.
  if (moveDist > 0.015 && Math.abs(obs.speed) > 0.08) {
    const velDir = Math.atan2(dy, dx);
    const measHead = velDir - (obs.speed < 0 ? PI : 0);
    const err = angleDiff(measHead, mem.hEst);
    let gain = 0.05;
    if (Math.abs(mem.lastCmdL - mem.lastCmdR) < 0.25) gain = 0.2;
    if (Math.abs(err) < 1.2) {
      mem.hEst = mem.hEst + err * gain;
      mem.bias = angleDiff(raw, mem.hEst);
    }
  } else {
    mem.hEst = raw - mem.bias;
  }
  mem.hEst = norm(mem.hEst);

  const targetDist = Math.hypot(obs.targetX - obs.x, obs.targetY - obs.y);
  const targetBearing = Math.atan2(obs.targetY - obs.y, obs.targetX - obs.x);
  const targetRel = angleDiff(targetBearing, mem.hEst);

  // Absolute arena-boundary repulsion, always active.
  const B = 1.8;
  let repX = 0;
  let repY = 0;
  if (obs.x < B) repX += (B - obs.x) * 1.5;
  if (obs.x > 40 - B) repX -= (obs.x - (40 - B)) * 1.5;
  if (obs.y < B) repY += (B - obs.y) * 1.5;
  if (obs.y > 40 - B) repY -= (obs.y - (40 - B)) * 1.5;
  const repMag = Math.hypot(repX, repY);
  let boundaryRel = 0;
  if (repMag > 0.01) {
    const repBearing = Math.atan2(repY, repX);
    boundaryRel = angleDiff(repBearing, mem.hEst);
  }

  let steer = 0;
  let base = 0.6;
  const inFollow = mem.followUntil > obs.t && mem.followSide !== 0;

  if (inFollow) {
    if (mem.followSide === 1) {
      steer = (leftClear - 0.7) * 2.0;
      if (front < 1.2) steer -= (1.2 - front) * 3.0;
      if (leftClear < 0.4) steer -= (0.4 - leftClear) * 5.0;
    } else {
      steer = -(rightClear - 0.7) * 2.0;
      if (front < 1.2) steer += (1.2 - front) * 3.0;
      if (rightClear < 0.4) steer += (0.4 - rightClear) * 5.0;
    }
    base = 0.4;
    if (front < 1.0) base *= 0.6;
    if (minSide < 0.5) base *= 0.7;
    if (front > 2.0 && Math.abs(targetRel) < 0.9 && repMag < 0.3) {
      mem.followUntil = -1;
    }
  } else {
    if (targetDist > 0.5) {
      let targetWeight = 1.6;
      if (repMag > 0.5) targetWeight *= clamp(1 - (repMag - 0.5) / 3, 0.2, 1);
      steer += targetRel * targetWeight;
    }

    if (front < 2.2) {
      steer += (leftClear - rightClear) * 1.8;
      if (front < 1.2) {
        steer += (leftClear > rightClear ? 1.8 : -1.8);
      }
    }
    if (leftClear < 1.0) steer -= (1.0 - leftClear) * 3.0;
    if (rightClear < 1.0) steer += (1.0 - rightClear) * 3.0;

    base = 0.75;
    const absRel = Math.abs(targetRel);
    if (absRel > 0.5) base = 0.6;
    if (absRel > 1.0) base = 0.4;
    if (absRel > 1.8) base = 0.25;
    if (front < 2.2) base *= clamp((front - 0.35) / 1.85, 0.15, 1);
    if (minSide < 1.0) base *= 0.75;
    if (repMag > 0.5) base *= 0.8;
    if (repMag > 1.5) base *= 0.7;
    if (targetDist < 1.2) base = Math.min(base, 0.45);
    if (obs.speed > 1.2) base *= 0.85;
  }

  if (repMag > 0.01) {
    steer += boundaryRel * 3.0 * clamp(repMag, 0, 2.5);
    if (inFollow && repMag > 1.0) mem.followUntil = -1;
  }

  const turn = clamp(steer, -2.5, 2.5) * 0.55;
  let left = base - turn;
  let right = base + turn;

  // Immediate close-obstacle overrides.
  if (front < 0.5) {
    const dir = leftClear > rightClear ? 1 : -1;
    left = -0.35 - dir * 0.35;
    right = -0.35 + dir * 0.35;
  } else if (front < 0.9 && minSide > 0.4) {
    const dir = leftClear > rightClear ? 1 : -1;
    left = 0.15 - dir * 0.4;
    right = 0.15 + dir * 0.4;
  }

  // Stuck detection and recovery.
  const cmdMag = Math.max(Math.abs(left), Math.abs(right));
  if (Math.abs(obs.speed) < 0.06 && cmdMag > 0.25 && obs.t > mem.recoverUntil) {
    mem.stuckTime += dt;
  } else {
    mem.stuckTime = Math.max(0, mem.stuckTime - dt * 0.5);
  }

  if (mem.stuckTime > 1.5 && obs.t > mem.recoverUntil) {
    mem.stuckCount++;
    if (mem.stuckCount >= 2) {
      mem.followUntil = obs.t + 4.0;
      mem.followSide = leftClear < rightClear ? 1 : -1;
      mem.stuckCount = 0;
      mem.stuckTime = 0;
    } else {
      mem.recoverUntil = obs.t + 0.8;
      mem.recoverDir = -(mem.recoverDir || 1);
      mem.stuckTime = 0;
    }
  }

  if (obs.t < mem.recoverUntil) {
    const dir = mem.recoverDir;
    if (front < 1.0) {
      left = -0.35 - dir * 0.35;
      right = -0.35 + dir * 0.35;
    } else {
      left = 0.25 - dir * 0.35;
      right = 0.25 + dir * 0.35;
    }
  }

  // Deadzone compensation.
  const DEAD = 0.2;
  if (left > 0 && left < DEAD) left = DEAD;
  else if (left < 0 && left > -DEAD) left = -DEAD;
  if (right > 0 && right < DEAD) right = DEAD;
  else if (right < 0 && right > -DEAD) right = -DEAD;

  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);
  mem.lastCmdL = left;
  mem.lastCmdR = right;

  return { left, right };
}
